(723, 'Большой аккумулятор', 'Большой перезаряжаемый аккумулятор. Должен быть заряжен как минимум на 5 секунд, прежде чем разрядить его. Может быть подключен на одной линии питания. Эффективность зарядки зависит от входящего питания, максимальный процент которой составляет 80%.', NULL, 1, 0, 10, 'large-rechargeable-battery', 20, 15, '', 1, 10, NULL, '553270375', '45.00', NULL, NULL, 1, 205, '2024-05-06 12:03:31'),
(724, 'Ветрогенератор', 'Конвертирует кинетическую энергию, полученную с ветра, в электрическую. Количество выходящей мощности напрямую зависит от скорости ветра. Сильные порывы ветра будут производить больше энергии.', NULL, 1, 0, 10, 'wind-turbine', 20, 15, '', 1, 0, NULL, '-1819763926', '60.00', NULL, NULL, 1, 206, '2024-05-06 12:03:33'),
(725, 'Водяной насос', 'Может быть помещен в источник воды, чтобы собрать эту воду при питании. Может быть подключено к другим элементам воды.', NULL, 0, 0, 10, 'water-pump', 20, 17, '', 0, 0, '', '-1284169891', '0.00', 2, NULL, 1, 1000, '2024-05-06 12:03:35'),
(726, 'Воспламенитель', 'При получении питания зажигает ближайшие объекты, вроде печей и костров.', NULL, 0, 0, 10, 'igniter', 20, NULL, '', 0, 0, NULL, '-44876289', '0.00', NULL, NULL, 1, 1000, '2024-05-06 12:03:37'),
